14	/// System that calculates auto-layout for UI elements
15	/// and applies the computed positions to Transform components.
16	/// Must run AFTER IntrinsicSizingSystem and BEFORE HierarchySystem.
17	/// </summary>
18	public class AutoLayoutSystem : ISystem<GameState>
19	{
20	    private readonly World _world;
21	    private readonly ViewportManager _viewport;
22	    private readonly FlexLayoutNode _screenRoot;
23	    private readonly EntitySet _slotEntities;
24	
25	    public AutoLayoutSystem(World world, ViewportManager viewport)
26	    {
27	        _world = world;
28	        _viewport = viewport;
29	
30	        // Create a screen root node that represents the virtual screen
31	        _screenRoot = new FlexLayoutNode
32	        {
33	            Width = viewport.VirtualWidth,
34	            Height = viewport.VirtualHeight,
35	            WidthAuto = false,
36	            HeightAuto = false
37	        };
38	
39	        // Query for all layout slots
40	        _slotEntities = world.GetEntities()
41	            .With<LayoutSlot>()
42	            .With<Transform>()
43	            .AsSet();
44	    }
45	
46	    public bool IsEnabled { get; set; } = true;
47	
48	    public void Update(GameState state)
49	    {
50	        if (!IsEnabled) return;
51	
52	        // Update screen root size in case viewport changed
53	        _screenRoot.Width = _viewport.VirtualWidth;
54	        _screenRoot.Height = _viewport.VirtualHeight;
55	
56	        // Clear and rebuild the layout tree
57	        _screenRoot.Clear();
58	
59	        // Find all root slots and build their trees
60	        var roots = new List<(Entity entity, ScreenAnchor anchor)>();
61	
62	        foreach (var entity in _slotEntities.GetEntities())
63	        {
64	            ref readonly var slot = ref entity.Get<LayoutSlot>();
65	            if (!slot.IsRoot) continue;
66	
67	            // Add this root to the screen root
68	            _screenRoot.AddChild(slot.Node);
69	            roots.Add((entity, slot.Anchor));
70	        }
71	
72	        // Calculate the layout
73	        _screenRoot.CalculateLayout(_viewport.VirtualWidth, _viewport.VirtualHeight);
74	
75	        // Apply layout results to transforms
76	        foreach (var (rootEntity, anchor) in roots)
77	        {
78	            var screenOffset = GetScreenAnchorOffset(anchor, rootEntity);
79	            ApplyLayout(rootEntity, screenOffset, isRoot: true);
80	        }
81	    }
82	
83	    /// <summary>
84	    /// Calculates the screen offset based on the anchor position.
85	    /// Layout uses top-left origin with Y increasing downward.
86	    /// MonoDreams uses center origin (0,0 at screen center).
87	    /// </summary>
88	    private Vector2 GetScreenAnchorOffset(ScreenAnchor anchor, Entity rootEntity)
89	    {
90	        var halfWidth = _viewport.VirtualWidth / 2f;
91	        var halfHeight = _viewport.VirtualHeight / 2f;
92	
93	        // Get the root's computed size to center it properly
94	        ref var slot = ref rootEntity.Get<LayoutSlot>();
95	        var rootWidth = slot.ComputedWidth;
96	        var rootHeight = slot.ComputedHeight;
97	
98	        // Calculate offset based on anchor
99	        // The offset converts from layout coordinates (top-left: 0,0) to MonoDreams coordinates (center: 0,0)
100	        return anchor switch
101	        {
102	            // Top row
103	            ScreenAnchor.TopLeft => new Vector2(-halfWidth, -halfHeight),
104	            ScreenAnchor.TopCenter => new Vector2(-rootWidth / 2, -halfHeight),
105	            ScreenAnchor.TopRight => new Vector2(halfWidth - rootWidth, -halfHeight),
106	
107	            // Middle row
108	            ScreenAnchor.CenterLeft => new Vector2(-halfWidth, -rootHeight / 2),
109	            ScreenAnchor.Center => new Vector2(-rootWidth / 2, -rootHeight / 2),
110	            ScreenAnchor.CenterRight => new Vector2(halfWidth - rootWidth, -rootHeight / 2),
111	
112	            // Bottom row
113	            ScreenAnchor.BottomLeft => new Vector2(-halfWidth, halfHeight - rootHeight),
114	            ScreenAnchor.BottomCenter => new Vector2(-rootWidth / 2, halfHeight - rootHeight),
115	            ScreenAnchor.BottomRight => new Vector2(halfWidth - rootWidth, halfHeight - rootHeight),
116	
117	            // Stretch fills the entire screen
118	            ScreenAnchor.Stretch => new Vector2(-halfWidth, -halfHeight),
119	
120	            _ => Vector2.Zero
121	        };
122	    }
123	
124	    /// <summary>
125	    /// Recursively applies layout results to Transform components.
126	    /// </summary>
127	    private void ApplyLayout(Entity entity, Vector2 offset, bool isRoot)
128	    {
129	        ref var slot = ref entity.Get<LayoutSlot>();
130	
131	        // Calculate position from layout results
132	        var localPos = new Vector2(slot.ComputedX, slot.ComputedY);
133	
134	        // Apply to transform
135	        if (entity.Has<Transform>())
136	        {
137	            ref var transform = ref entity.Get<Transform>();
138	            if (isRoot)
139	            {
140	                // Root slots get the full offset applied
141	                transform.Position = offset + localPos;
142	            }
143	            else
144	            {
145	                // Child slots only get local position (relative to parent via Transform.Parent)
146	                transform.Position = localPos;
147	            }
148	        }
149	
150	        // Recurse to child nodes in the FlexLayoutNode hierarchy
151	        foreach (var childNode in slot.Node.Children)
152	        {
153	            // Find the entity that owns this FlexLayoutNode
154	            var childEntity = FindEntityByNode(childNode);
155	            if (childEntity.HasValue && childEntity.Value.IsAlive)
156	            {
157	                ApplyLayout(childEntity.Value, offset, isRoot: false);
158	            }
159	        }
160	    }
161	
162	    /// <summary>
163	    /// Finds the entity that has a LayoutSlot with the given FlexLayoutNode.
164	    /// </summary>
165	    private Entity? FindEntityByNode(FlexLayoutNode node)
166	    {
167	        foreach (var entity in _slotEntities.GetEntities())
168	        {
169	            ref readonly var slot = ref entity.Get<LayoutSlot>();
170	            if (slot.Node == node)
171	            {
172	                return entity;
173	            }
174	        }
175	        return null;
176	    }
177	
178	    public void Dispose()
179	    {
180	        _slotEntities.Dispose();
181	        _screenRoot.Clear();
182	    }
183	}
