2	using System.Collections.Generic;
3	using DefaultEcs;
4	using DefaultEcs.System;
5	using Microsoft.Xna.Framework;
6	using Microsoft.Xna.Framework.Graphics;
7	using MonoDreams.Component.Draw;
8	using MonoDreams.Examples.Component.Layout;
9	using MonoDreams.State;
10	using MonoGame.Extended.BitmapFonts;
11	
12	namespace MonoDreams.Examples.System.Layout;
13	
14	/// <summary>
15	/// Debug visualization system for auto layout.
16	/// Renders rectangle boundaries and node names for layout debugging.
17	/// </summary>
18	public class LayoutDebugSystem : ISystem<GameState>
19	{
20	    /// <summary>
21	    /// Global toggle for layout debug visualization.
22	    /// </summary>
23	    public static bool Enabled = false;
24	
25	    private static readonly Color[] DepthColors =
26	    [
27	        new Color(100, 149, 237),  // Cornflower Blue - depth 0
28	        new Color(50, 205, 50),    // Lime Green - depth 1
29	        new Color(255, 165, 0),    // Orange - depth 2
30	        new Color(186, 85, 211),   // Medium Orchid - depth 3+
31	    ];
32	
33	    private const float LineThickness = 1f;
34	    private const float LabelScale = 0.08f;
35	    private const float DebugLayerDepth = 0.99f;
36	
37	    private readonly World _world;
38	    private readonly EntitySet _layoutEntities;
39	    private readonly BitmapFont _font;
40	    private readonly RenderTargetID _renderTarget;
41	    private readonly MonoDreams.Component.Camera _camera;
42	
43	    // Track debug entities for cleanup
44	    private readonly List<Entity> _debugEntities = [];
45	
46	    public LayoutDebugSystem(World world, BitmapFont font, MonoDreams.Component.Camera camera, RenderTargetID renderTarget = RenderTargetID.Main)
47	    {
48	        _world = world;
49	        _font = font;
50	        _camera = camera;
51	        _renderTarget = renderTarget;
52	
53	        _layoutEntities = world.GetEntities()
54	            .With<LayoutSlot>()
55	            .With<MonoDreams.Component.Transform>()
56	            .AsSet();
57	    }
58	
59	    public bool IsEnabled { get; set; } = true;
60	
61	    public void Update(GameState state)
62	    {
63	        // Clean up old debug entities
64	        foreach (var entity in _debugEntities)
65	        {
66	            if (entity.IsAlive)
67	            {
68	                entity.Dispose();
69	            }
70	        }
71	        _debugEntities.Clear();
72	
73	        if (!IsEnabled || !Enabled) return;
74	
75	        // Create debug visuals for each layout node
76	        foreach (var entity in _layoutEntities.GetEntities())
77	        {
78	            ref readonly var slot = ref entity.Get<LayoutSlot>();
79	            ref readonly var transform = ref entity.Get<MonoDreams.Component.Transform>();
80	
81	            // Calculate hierarchy depth for coloring
82	            var depth = CalculateDepth(slot.Node);
83	            var color = DepthColors[global::System.Math.Min(depth, DepthColors.Length - 1)];
84	
85	            // Get computed layout bounds
86	            // Use Position (not WorldPosition) because layout containers don't have Origin offset
87	            // Position is the top-left corner set by AutoLayoutSystem
88	            var pos = transform.Position;
89	            var width = slot.ComputedWidth;
90	            var height = slot.ComputedHeight;
91	
92	            // Create rectangle from top-left to bottom-right
93	            var x = pos.X;
94	            var y = pos.Y;
95	
96	            // Create bounding rectangle entity
97	            CreateBoundsEntity(x, y, width, height, color);
98	
99	            // Create label entity if node has a name
100	            if (!string.IsNullOrEmpty(slot.Node.Name))
101	            {
102	                CreateLabelEntity(slot.Node.Name, x, y, color);
103	            }
104	        }
105	    }
106	
107	    private int CalculateDepth(MonoDreams.Examples.Layout.FlexLayoutNode node)
108	    {
109	        var depth = 0;
110	        var current = node.Parent;
111	        while (current != null)
112	        {
113	            depth++;
114	            current = current.Parent;
115	        }
116	        return depth;
117	    }
118	
119	    private void CreateBoundsEntity(float x, float y, float width, float height, Color color)
120	    {
121	        var entity = _world.CreateEntity();
122	        _debugEntities.Add(entity);
123	
124	        // Calculate corners
125	        var topLeft = new Vector2(x, y);
126	        var topRight = new Vector2(x + width, y);
127	        var bottomRight = new Vector2(x + width, y + height);
128	        var bottomLeft = new Vector2(x, y + height);
129	
130	        // Build mesh for rectangle outline
131	        var vertices = new List<VertexPositionColor>();
132	        var indices = new List<int>();
133	        var indexOffset = 0;
134	
135	        AddThickLine(vertices, indices, topLeft, topRight, LineThickness, color, ref indexOffset);
136	        AddThickLine(vertices, indices, topRight, bottomRight, LineThickness, color, ref indexOffset);
137	        AddThickLine(vertices, indices, bottomRight, bottomLeft, LineThickness, color, ref indexOffset);
138	        AddThickLine(vertices, indices, bottomLeft, topLeft, LineThickness, color, ref indexOffset);
139	
140	        entity.Set(new DrawComponent
141	        {
142	            Type = DrawElementType.Mesh,
143	            Vertices = vertices.ToArray(),
144	            Indices = indices.ToArray(),
145	            PrimitiveType = PrimitiveType.TriangleList,
146	            Target = _renderTarget,
147	            LayerDepth = DebugLayerDepth
148	        });
149	    }
150	
151	    private void CreateLabelEntity(string name, float x, float y, Color color)
152	    {
153	        var entity = _world.CreateEntity();
154	        _debugEntities.Add(entity);
155	
156	        // Position label at top-left corner, slightly offset
157	        var labelPos = new Vector2(x + 4, y + 2);
158	
159	        entity.Set(new MonoDreams.Component.Transform(labelPos));
160	        entity.Set(new DrawComponent
161	        {
162	            Type = DrawElementType.Text,
163	            Font = _font,
164	            Text = name,
165	            Position = labelPos,
166	            Color = color,
167	            Scale = new Vector2(LabelScale),
168	            Target = _renderTarget,
169	            LayerDepth = DebugLayerDepth
170	        });
171	    }
172	
173	    private void AddThickLine(List<VertexPositionColor> vertices, List<int> indices,
174	        Vector2 start, Vector2 end, float thickness, Color color, ref int indexOffset)
175	    {
176	        var direction = end - start;
177	        if (direction.LengthSquared() < 0.0001f) return;
178	
179	        var perpendicular = new Vector2(-direction.Y, direction.X);
180	        perpendicular.Normalize();
181	        perpendicular *= thickness / 2;
182	
183	        vertices.Add(new VertexPositionColor(new Vector3(start + perpendicular, 0), color));
184	        vertices.Add(new VertexPositionColor(new Vector3(start - perpendicular, 0), color));
185	        vertices.Add(new VertexPositionColor(new Vector3(end - perpendicular, 0), color));
186	        vertices.Add(new VertexPositionColor(new Vector3(end + perpendicular, 0), color));
187	
188	        indices.Add(indexOffset);
189	        indices.Add(indexOffset + 1);
190	        indices.Add(indexOffset + 2);
191	
192	        indices.Add(indexOffset);
193	        indices.Add(indexOffset + 2);
194	        indices.Add(indexOffset + 3);
195	
196	        indexOffset += 4;
197	    }
198	
199	    public void Dispose()
200	    {
201	        foreach (var entity in _debugEntities)
202	        {
203	            if (entity.IsAlive)
204	            {
205	                entity.Dispose();
206	            }
207	        }
208	        _debugEntities.Clear();
209	        _layoutEntities.Dispose();
210	    }
211	}
