31	using Visible = MonoDreams.Component.Draw.Visible;
32	
33	namespace MonoDreams.Examples.Screens;
34	
35	/// <summary>
36	/// Screen for selecting which level to load.
37	/// </summary>
38	public class LevelSelectionScreen : IGameScreen
39	{
40	    private readonly ContentManager _content;
41	    private readonly Game _game;
42	    private readonly GraphicsDevice _graphicsDevice;
43	    private readonly Camera _camera;
44	    private readonly ViewportManager _viewportManager;
45	    private readonly DefaultParallelRunner _parallelRunner;
46	    private readonly SpriteBatch _spriteBatch;
47	    private readonly World _world;
48	    private readonly Dictionary<RenderTargetID, RenderTarget2D> _renderTargets;
49	    private readonly BitmapFont _font;
50	    private readonly DrawLayerMap _layers;
51	
52	    public LevelSelectionScreen(Game game, GraphicsDevice graphicsDevice, ContentManager content, Camera camera,
53	        ViewportManager viewportManager, DefaultParallelRunner parallelRunner, SpriteBatch spriteBatch)
54	    {
55	        _game = game;
56	        _graphicsDevice = graphicsDevice;
57	        _content = content;
58	        _camera = camera;
59	        _viewportManager = viewportManager;
60	        _parallelRunner = parallelRunner;
61	        _spriteBatch = spriteBatch;
62	        _renderTargets = new Dictionary<RenderTargetID, RenderTarget2D>
63	        {
64	            { RenderTargetID.Main, new RenderTarget2D(graphicsDevice, _viewportManager.VirtualWidth, _viewportManager.VirtualHeight) },
65	            { RenderTargetID.UI, new RenderTarget2D(graphicsDevice, _viewportManager.VirtualWidth, _viewportManager.VirtualHeight) },
66	            { RenderTargetID.HUD, new RenderTarget2D(graphicsDevice, _viewportManager.VirtualWidth, _viewportManager.VirtualHeight) }
67	        };
68	
69	        // Load font early so it's available for systems
70	        _font = content.Load<BitmapFont>("Fonts/UAV-OSD-Sans-Mono-72-White-fnt");
71	
72	        camera.Position = Vector2.Zero;
73	
74	        _layers = DrawLayerMap.FromEnum<DrawLayer>();
75	        _world = new World();
76	        UpdateSystem = CreateUpdateSystem();
77	        DrawSystem = CreateDrawSystem();
78	    }
79	
80	    private ScreenController? _screenController;
81	
82	    public ISystem<GameState> UpdateSystem { get; }
83	    public ISystem<GameState> DrawSystem { get; }
84	    public World World => _world;
85	
86	    public void Load(ScreenController screenController, ContentManager content)
87	    {
88	        _screenController = screenController;
89	
90	        // Subscribe to screen transition requests
91	        _world.Subscribe<ScreenTransitionRequest>(OnScreenTransitionRequest);
92	
93	        var cursorTextures = new Dictionary<CursorType, Texture2D>
94	        {
95	            [CursorType.Default] = content.Load<Texture2D>("Mouse sprites/Triangle Mouse icon 1"),
96	            [CursorType.Pointer] = content.Load<Texture2D>("Mouse sprites/Triangle Mouse icon 2"),
97	            [CursorType.Hand] = content.Load<Texture2D>("Mouse sprites/Catpaw Mouse icon"),
98	        };
99	
100	        // Create cursor entity
101	        Objects.Cursor.Create(_world, cursorTextures, RenderTargetID.HUD);
102	
103	        // Create level selection UI
104	        CreateLevelSelectionUI();
105	    }
106	
107	    [Subscribe]
108	    private void OnScreenTransitionRequest(in ScreenTransitionRequest request)
109	    {
110	        // Store the requested level in the world so the next screen can access it
111	        if (request.LevelIdentifier != null)
112	        {
113	            _screenController?.Game.Services.AddService(new RequestedLevelComponent(request.LevelIdentifier));
114	        }
115	
116	        // Transition to the requested screen
117	        _screenController?.LoadScreen(request.ScreenName);
118	    }
119	
120	    private void CreateLevelSelectionUI()
121	    {
122	        // Lofi color palette
123	        var darkBrown = new Color(60, 50, 45);        // Main text color
124	        var terracotta = new Color(200, 120, 80);     // Hover/accent color
125	        var mutedBrown = new Color(150, 140, 130);    // Disabled color
126	
127	        // Create button style
128	        var buttonStyle = ButtonStyle.WithColors(darkBrown, terracotta, mutedBrown);
129	
130	        // Create entities first
131	        var titleEntity = CreateTextEntity("Select Level", _font, darkBrown, scale: 0.3f, _layers.GetDepth(DrawLayer.Title));
132	        var button1 = CreateButtonEntity("Level 1", _font, 0, "Level_0", true, buttonStyle);
133	        var button2 = CreateButtonEntity("Level 2", _font, 1, "Blender_Level", true, buttonStyle);
134	        var button3 = CreateButtonEntity("Level 3", _font, 2, null, true, buttonStyle, ScreenName.InfiniteRunner);
135	
136	        // Create UI using auto layout with slots
137	        var layout = new AutoLayoutBuilder(_world, _viewportManager);
138	
139	        layout.CreateRoot(ScreenAnchor.Center)
140	            .Name("Root")
141	            .Direction(LayoutDirection.Vertical)
142	            .Gap(40)
143	            .AlignMain(MainAxisAlignment.Center)
144	            .AlignCross(CrossAxisAlignment.Center)
145	            .AddSlot(slot => slot
146	                .Attach(titleEntity)
147	                .MeasureWith(MeasureText))
148	            .AddContainer(row => row
149	                .Name("ButtonColumn")
150	                .Direction(LayoutDirection.Vertical)
151	                .Gap(50)
152	                .AlignCross(CrossAxisAlignment.Center)
153	                .AddSlot(slot => slot.Attach(button1.container).MeasureWith(_ => button1.size))
154	                .AddSlot(slot => slot.Attach(button2.container).MeasureWith(_ => button2.size))
155	                .AddSlot(slot => slot.Attach(button3.container).MeasureWith(_ => button3.size))
156	            )
157	            .Build();
158	    }
159	
160	    private Entity CreateTextEntity(string text, BitmapFont font, Color color, float scale, float layerDepth)
161	    {
162	        var entity = _world.CreateEntity();
163	        entity.Set(new Transform(Vector2.Zero));
164	        entity.Set(new DynamicText
165	        {
166	            Target = RenderTargetID.Main,
167	            LayerDepth = layerDepth,
168	            TextContent = text,
169	            Font = font,
170	            Color = color,
171	            Scale = scale,
172	            IsRevealed = true,
173	            VisibleCharacterCount = int.MaxValue
174	        });
175	        entity.Set<Visible>();
176	        return entity;
177	    }
178	
179	    private (Entity container, Vector2 size) CreateButtonEntity(
180	        string text,
181	        BitmapFont font,
182	        int levelIndex,
183	        string levelName,
184	        bool isClickable,
185	        ButtonStyle style,
186	        string targetScreen = null)
187	    {
188	        // Measure text to determine button size
189	        var textSize = font.MeasureString(text) * style.TextScale;
190	        var buttonSize = new Vector2(
191	            textSize.Width + style.Padding * 2,
192	            textSize.Height + style.Padding * 2);
193	
194	        // Create button container entity
195	        var buttonContainerEntity = _world.CreateEntity();
196	        var buttonTransform = new Transform(Vector2.Zero);
197	        buttonContainerEntity.Set(buttonTransform);
