28	public class DialogueSystem : ISystem<GameState>
29	{
30	    private readonly World _world;
31	    private readonly Entity _rootEntity;
32	    private readonly DialogueState _dialogueState;
33	    private readonly BitmapFont _font;
34	    private readonly Transform _rootTransform;
35	    private readonly DrawLayerMap _layers;
36	
37	    // Yarn runtime
38	    private readonly Yarn.Dialogue _yarnDialogue;
39	    private readonly DialogueRunner _dialogueRunner;
40	    private readonly InMemoryVariableStorage _variableStorage;
41	
42	    public bool IsEnabled { get; set; } = true;
43	
44	    public DialogueSystem(World world, ContentManager content, GraphicsDevice graphicsDevice, int virtualWidth, int virtualHeight, DrawLayerMap layers, IEnumerable<string> dialogueContentPaths = null)
45	    {
46	        _world = world;
47	        _layers = layers ?? throw new ArgumentNullException(nameof(layers));
48	        world.Subscribe(this);
49	
50	        // Load assets
51	        var dialogBoxTexture = content.Load<Texture2D>("Dialouge UI/dialog box medium");
52	        _font = content.Load<BitmapFont>("Fonts/PPMondwest-Regular-fnt");
53	        var indicatorSheet = content.Load<Texture2D>("Dialouge UI/dialog box character finished talking click to continue indicator - spritesheet");
54	        var indicatorTexture = indicatorSheet.Crop(new Rectangle(96, 0, 16, 16), graphicsDevice);
55	
56	        // Layout constants (UI coordinates, virtual resolution)
57	        var boxWidth = virtualWidth - 40;
58	        var boxHeight = 120;
59	        var rootPosition = new Vector2(20, virtualHeight - boxHeight - 20);
60	        var textOffset = new Vector2(16, 16);
61	        const int indicatorSize = 32;
62	        var indicatorOffset = new Vector2(boxWidth - indicatorSize - 12, boxHeight - indicatorSize - 8);
63	
64	        // Create root entity
65	        _rootTransform = new Transform(rootPosition);
66	        _rootEntity = world.CreateEntity();
67	        _rootEntity.Set(new EntityInfo(nameof(EntityType.Interface), "DialogueRoot"));
68	        _rootEntity.Set(_rootTransform);
69	        _dialogueState = new DialogueState();
70	        _rootEntity.Set(_dialogueState);
71	
72	        // Create box child entity
73	        _dialogueState.BoxEntity = world.CreateEntity();
74	        _dialogueState.BoxEntity.Set(new EntityInfo(nameof(EntityType.Interface), "DialogueBox"));
75	        _dialogueState.BoxEntity.Set(new Transform());
76	        _dialogueState.BoxEntity.SetParent(_rootEntity);
77	        _dialogueState.BoxEntity.Set(new SpriteInfo
78	        {
79	            SpriteSheet = dialogBoxTexture,
80	            Source = new Rectangle(0, 0, dialogBoxTexture.Width, dialogBoxTexture.Height),
81	            Size = new Vector2(boxWidth, boxHeight),
82	            Color = Color.White,
83	            Target = RenderTargetID.UI,
84	            LayerDepth = _layers.GetDepth(GameDrawLayer.DialogueUI),
85	            NinePatchData = new NinePatchInfo(
86	                23,
87	                new Rectangle(0, 0, 23, 23),
88	                new Rectangle(23, 0, 1, 23),
89	                new Rectangle(24, 0, 23, 23),
90	                new Rectangle(0, 23, 23, 1),
91	                new Rectangle(23, 23, 1, 1),
92	                new Rectangle(24, 23, 23, 1),
93	                new Rectangle(0, 24, 23, 23),
94	                new Rectangle(23, 24, 1, 23),
95	                new Rectangle(24, 24, 23, 23))
96	        });
97	        _dialogueState.BoxEntity.Set(new DrawComponent
98	        {
99	            Type = DrawElementType.Sprite,
100	            Target = RenderTargetID.UI
101	        });
102	
103	        // Create text child entity
104	        _dialogueState.TextEntity = world.CreateEntity();
105	        _dialogueState.TextEntity.Set(new EntityInfo(nameof(EntityType.Interface), "DialogueText"));
106	        _dialogueState.TextEntity.Set(new Transform(textOffset));
107	        _dialogueState.TextEntity.SetParent(_rootEntity);
108	        _dialogueState.TextEntity.Set(new DynamicText
109	        {
110	            Target = RenderTargetID.UI,
111	            LayerDepth = _layers.GetDepth(GameDrawLayer.DialogueUI, +0.01f),
112	            Font = _font,
113	            Color = Color.SaddleBrown,
114	            Scale = 0.5f,
115	            RevealingSpeed = 20,
116	            RevealStartTime = float.NaN,
117	            IsRevealed = false,
118	            VisibleCharacterCount = 0,
119	            TextContent = ""
120	        });
121	        _dialogueState.TextEntity.Set(new DrawComponent
122	        {
123	            Type = DrawElementType.Text,
124	            Target = RenderTargetID.UI
125	        });
126	
127	        // Create indicator child entity
128	        _dialogueState.IndicatorEntity = world.CreateEntity();
129	        _dialogueState.IndicatorEntity.Set(new EntityInfo(nameof(EntityType.Interface), "DialogueIndicator"));
130	        _dialogueState.IndicatorEntity.Set(new Transform(indicatorOffset));
131	        _dialogueState.IndicatorEntity.SetParent(_rootEntity);
132	        _dialogueState.IndicatorEntity.Set(new SpriteInfo
133	        {
134	            SpriteSheet = indicatorTexture,
135	            Source = new Rectangle(0, 0, indicatorTexture.Width, indicatorTexture.Height),
136	            Size = new Vector2(indicatorSize, indicatorSize),
137	            Color = Color.White,
138	            Target = RenderTargetID.UI,
139	            LayerDepth = _layers.GetDepth(GameDrawLayer.DialogueUI, +0.01f)
140	        });
141	        _dialogueState.IndicatorEntity.Set(new DrawComponent
142	        {
143	            Type = DrawElementType.Sprite,
144	            Target = RenderTargetID.UI
145	        });
146	
147	        // Set up Yarn runtime
148	        var paths = dialogueContentPaths ?? new[] { "Dialogues/hello_world" };
149	        _dialogueRunner = new DialogueRunner();
150	        _variableStorage = new InMemoryVariableStorage();
151	        _yarnDialogue = new Yarn.Dialogue(_variableStorage)
152	        {
153	            LogDebugMessage = msg => global::System.Diagnostics.Debug.WriteLine($"[Yarn] {msg}"),
154	            LogErrorMessage = msg => global::System.Diagnostics.Debug.WriteLine($"[Yarn ERROR] {msg}"),
155	            LineHandler = OnYarnLine,
