182	    // --- Yarn callbacks (fire synchronously during Continue()) ---
183	
184	    private void OnYarnLine(Line line)
185	    {
186	        var text = _dialogueRunner.GetLocalizedTextForLine(line);
187	
188	        // Parse "Speaker: text" format
189	        string? speaker = null;
190	        var displayText = text;
191	        var colonIndex = text.IndexOf(':');
192	        if (colonIndex > 0 && colonIndex < 30)
193	        {
194	            speaker = text[..colonIndex].Trim();
195	            displayText = text[(colonIndex + 1)..].Trim();
196	        }
197	
198	        _dialogueState.CurrentPhase = DialoguePhase.Line;
199	        _dialogueState.CurrentSpeaker = speaker;
200	        _dialogueState.WaitingForInput = false;
201	
202	        // Set text content and reset reveal animation
203	        ref var dynamicText = ref _dialogueState.TextEntity.Get<DynamicText>();
204	        dynamicText.TextContent = displayText;
205	        dynamicText.VisibleCharacterCount = 0;
206	        dynamicText.IsRevealed = false;
207	        dynamicText.RevealStartTime = float.NaN;
208	
209	        HideIndicator();
210	        HideOptions();
211	    }
212	
213	    private void OnYarnOptions(OptionSet optionSet)
214	    {
215	        _dialogueState.CurrentPhase = DialoguePhase.Options;
216	        _dialogueState.CurrentOptions.Clear();
217	        _dialogueState.CurrentOptionIDs.Clear();
218	        _dialogueState.SelectedOptionIndex = 0;
219	        _dialogueState.WaitingForInput = true;
220	
221	        foreach (var option in optionSet.Options)
222	        {
223	            if (!option.IsAvailable) continue;
224	            var text = _dialogueRunner.GetLocalizedTextForLine(option.Line);
225	            _dialogueState.CurrentOptions.Add(text);
226	            _dialogueState.CurrentOptionIDs.Add(option.ID);
227	        }
228	
229	        // Clear the main text line
230	        ref var dynamicText = ref _dialogueState.TextEntity.Get<DynamicText>();
231	        dynamicText.TextContent = "";
232	        dynamicText.VisibleCharacterCount = 0;
233	
234	        ShowOptions();
235	        HideIndicator();
236	    }
