268	    // --- Collision trigger ---
269	
270	    [Subscribe]
271	    private void OnCollision(in CollisionMessage message)
272	    {
273	        if (message.Type != CollisionType.Dialogue) return;
274	        if (_dialogueState.IsActive || _dialogueState.WasTriggered) return;
275	
276	        var zoneEntity = message.CollidingEntity;
277	        var nodeName = "HelloWorld";
278	
279	        if (zoneEntity.Has<DialogueZoneComponent>())
280	        {
281	            var zone = zoneEntity.Get<DialogueZoneComponent>();
282	            if (zone.OneTimeOnly && zone.HasBeenTriggered) return;
283	            nodeName = zone.YarnNodeName;
284	            zone.HasBeenTriggered = true;
285	        }
286	
287	        StartYarnDialogue(nodeName);
288	    }
289	
290	    public void StartYarnDialogue(string nodeName)
291	    {
292	        _dialogueState.IsActive = true;
293	        _dialogueState.WasTriggered = true;
294	
295	        // The Interact press that opened this dialogue may still be held this same
296	        // frame. Consume the edge so DialogueSystem.Update (later in this tick)
297	        // doesn't read JustPressed and advance the first line on its own opening.
298	        InputState.Interact.Consume();
299	
300	        // Show dialogue box
301	        _dialogueState.BoxEntity.Set<Visible>();
302	
303	        _world.Publish(new DialogueActiveMessage(true));
304	
305	        // Start the yarn node — fires LineHandler or OptionsHandler synchronously
306	        _yarnDialogue.SetNode(nodeName);
307	        _yarnDialogue.Continue();
308	    }
309	
310	    // --- Update loop ---
311	
312	    public void Update(GameState state)
313	    {
314	        if (!_dialogueState.IsActive) return;
315	
316	        switch (_dialogueState.CurrentPhase)
317	        {
318	            case DialoguePhase.Line:
319	                UpdateLinePhase(InputState.Interact.JustPressed());
320	                break;
321	            case DialoguePhase.Options:
322	                UpdateOptionsPhase(
323	                    InputState.Up.JustPressed(),
324	                    InputState.Down.JustPressed(),
325	                    InputState.Interact.JustPressed());
326	                break;
327	        }
328	    }
329	
330	    private void UpdateLinePhase(bool interactJustPressed)
331	    {
332	        ref var dynamicText = ref _dialogueState.TextEntity.Get<DynamicText>();
333	
334	        if (dynamicText.IsRevealed)
335	        {
336	            if (!_dialogueState.IndicatorEntity.Has<Visible>())
337	                _dialogueState.IndicatorEntity.Set<Visible>();
338	            _dialogueState.WaitingForInput = true;
339	        }
340	        else
341	        {
342	            HideIndicator();
343	        }
344	
345	        if (!interactJustPressed) return;
346	
347	        if (!dynamicText.IsRevealed)
348	        {
349	            // Skip reveal — show all text immediately
350	            dynamicText.VisibleCharacterCount = dynamicText.TextContent?.Length ?? 0;
351	            dynamicText.IsRevealed = true;
352	        }
353	        else
354	        {
355	            // Advance to next yarn content
356	            _yarnDialogue.Continue();
357	        }
358	    }
359	
360	    private void UpdateOptionsPhase(bool upJustPressed, bool downJustPressed, bool interactJustPressed)
361	    {
362	        if (upJustPressed)
363	        {
364	            _dialogueState.SelectedOptionIndex =
365	                Math.Max(0, _dialogueState.SelectedOptionIndex - 1);
366	            UpdateOptionHighlights();
367	        }
368	        else if (downJustPressed)
369	        {
370	            _dialogueState.SelectedOptionIndex =
371	                Math.Min(_dialogueState.CurrentOptions.Count - 1, _dialogueState.SelectedOptionIndex + 1);
372	            UpdateOptionHighlights();
373	        }
374	
375	        if (interactJustPressed)
376	        {
377	            var yarnOptionID = _dialogueState.CurrentOptionIDs[_dialogueState.SelectedOptionIndex];
378	            HideOptions();
379	            _yarnDialogue.SetSelectedOption(yarnOptionID);
380	            _yarnDialogue.Continue();
381	        }
382	    }
383	
384	    // --- Option entity management ---
385	
386	    private void ShowOptions()
387	    {
388	        HideOptions();
389	
390	        const float startY = 16f;
391	        const float optionSpacing = 24f;
392	
393	        for (var i = 0; i < _dialogueState.CurrentOptions.Count; i++)
394	        {
395	            var prefix = i == _dialogueState.SelectedOptionIndex ? "> " : "  ";
396	            var fullText = prefix + _dialogueState.CurrentOptions[i];
397	
398	            var optionEntity = _world.CreateEntity();
399	            optionEntity.Set(new EntityInfo(nameof(EntityType.Interface), $"DialogueOption{i}"));
400	            optionEntity.Set(new Transform(new Vector2(16, startY + i * optionSpacing)));
401	            optionEntity.SetParent(_rootEntity);
402	            optionEntity.Set(new DynamicText
403	            {
404	                Target = RenderTargetID.UI,
405	                LayerDepth = _layers.GetDepth(GameDrawLayer.DialogueUI, +0.01f),
406	                Font = _font,
407	                Color = i == _dialogueState.SelectedOptionIndex ? Color.White : Color.SaddleBrown,
408	                Scale = 0.5f,
409	                RevealingSpeed = 0, // Instant reveal
410	                RevealStartTime = 0,
411	                IsRevealed = true,
412	                VisibleCharacterCount = fullText.Length,
413	                TextContent = fullText
414	            });
415	            optionEntity.Set(new DrawComponent
416	            {
417	                Type = DrawElementType.Text,
418	                Target = RenderTargetID.UI
419	            });
420	            optionEntity.Set<Visible>();
421	
422	            _dialogueState.OptionEntities.Add(optionEntity);
423	        }
424	    }
425	
426	    private void UpdateOptionHighlights()
427	    {
428	        for (var i = 0; i < _dialogueState.OptionEntities.Count; i++)
429	        {
430	            var entity = _dialogueState.OptionEntities[i];
431	            if (!entity.IsAlive) continue;
432	
433	            ref var dt = ref entity.Get<DynamicText>();
434	            var prefix = i == _dialogueState.SelectedOptionIndex ? "> " : "  ";
435	            dt.TextContent = prefix + _dialogueState.CurrentOptions[i];
436	            dt.VisibleCharacterCount = dt.TextContent.Length;
437	            dt.Color = i == _dialogueState.SelectedOptionIndex ? Color.White : Color.SaddleBrown;
438	        }
439	    }
440	
441	    private void HideOptions()
442	    {
443	        foreach (var entity in _dialogueState.OptionEntities)
444	        {
445	            if (entity.IsAlive) entity.Dispose();
446	        }
447	        _dialogueState.OptionEntities.Clear();
448	    }
449	
450	    private void HideIndicator()
451	    {
452	        if (_dialogueState.IndicatorEntity.Has<Visible>())
453	            _dialogueState.IndicatorEntity.Remove<Visible>();
454	
455	        // UI render target always renders regardless of Visible — clear the texture
456	        // so MasterRenderSystem skips drawing the stale DrawComponent.
457	        ref var indicatorDraw = ref _dialogueState.IndicatorEntity.Get<DrawComponent>();
458	        indicatorDraw.Texture = null;
459	    }
460	
461	    // --- Deactivation ---
462	
463	    private void DeactivateDialogue()
464	    {
465	        _dialogueState.IsActive = false;
466	        _dialogueState.WasTriggered = false;
467	        _dialogueState.CurrentPhase = DialoguePhase.None;
468	        _dialogueState.WaitingForInput = false;
469	        _dialogueState.CurrentSpeaker = null;
470	
471	        HideOptions();
472	
473	        // Hide box
474	        if (_dialogueState.BoxEntity.Has<Visible>())
475	            _dialogueState.BoxEntity.Remove<Visible>();
476	
477	        var boxDraw = _dialogueState.BoxEntity.Get<DrawComponent>();
478	        boxDraw.Texture = null;
479	
480	        // Clear text
481	        ref var dynamicText = ref _dialogueState.TextEntity.Get<DynamicText>();
482	        dynamicText.VisibleCharacterCount = 0;
483	        dynamicText.IsRevealed = false;
484	        dynamicText.TextContent = "";
485	
486	        var textDraw = _dialogueState.TextEntity.Get<DrawComponent>();
487	        textDraw.Text = null;
488	        textDraw.Font = null;
489	
490	        // Hide indicator
491	        HideIndicator();
492	        var indicatorDraw = _dialogueState.IndicatorEntity.Get<DrawComponent>();
493	        indicatorDraw.Texture = null;
494	
495	        _world.Publish(new DialogueActiveMessage(false));
496	    }
497	
498	    public void Dispose()
499	    {
500	        GC.SuppressFinalize(this);
501	    }
502	}
