python3 <<'PYEOF'
import json, os, glob, sys

errors = []
all_sources = set()

for manifest_path in sorted(glob.glob('registry/*/block.json')):
    with open(manifest_path) as f:
        m = json.load(f)
    name = m.get('name', '?')
    dir_name = os.path.basename(os.path.dirname(manifest_path))
    if name != dir_name:
        errors.append(f"{manifest_path}: name='{name}' != dir '{dir_name}'")
    for fi in m.get('files', []):
        src = fi['source']
        if not os.path.exists(src):
            errors.append(f"{name}: missing source '{src}'")
        if src in all_sources:
            errors.append(f"{name}: duplicate source '{src}' (also in another block)")
        all_sources.add(src)
    deps = m.get('dependencies', [])
    for d in deps:
        if not os.path.exists(f'registry/{d}/block.json'):
            errors.append(f"{name}: dep '{d}' has no manifest")

# coverage report
core_cs = set()
for root, _, files in os.walk('MonoDreams'):
    if 'bin' in root or 'obj' in root: continue
    for fn in files:
        if fn.endswith('.cs'):
            core_cs.add(os.path.join(root, fn).replace(os.sep, '/'))

uncovered = core_cs - all_sources
covered_ratio = len(core_cs & all_sources) / len(core_cs) * 100

print(f"Manifests scanned: {len(glob.glob('registry/*/block.json'))}")
print(f"Source files referenced: {len(all_sources)}")
print(f"Core .cs files: {len(core_cs)}")
print(f"Coverage: {covered_ratio:.1f}%")
print()
if uncovered:
    print("UNCOVERED FILES (in MonoDreams/ but no block claims them):")
    for f in sorted(uncovered): print(f"  {f}")
print()
if errors:
    print("ERRORS:")
    for e in errors: print(f"  {e}")
    sys.exit(1)
else:
    print("OK — every block source exists, no duplicates, no dangling deps.")
PYEOF

