using System.Text.Json;

namespace MonoDreams.Cli.Manifest;

internal sealed class Registry
{
    public string Root { get; }
    public string EngineRoot { get; }
    public RegistryIndex Index { get; }

    private readonly Dictionary<string, BlockManifest> _manifests = new();

    private Registry(string root, RegistryIndex index)
    {
        Root = root;
        EngineRoot = Path.GetFullPath(Path.Combine(root, ".."));
        Index = index;
    }

    public static Registry Load(string? explicitPath)
    {
        var path = Locate(explicitPath);
        var indexPath = Path.Combine(path, "index.json");
        if (!File.Exists(indexPath))
            throw new FileNotFoundException($"Registry index not found at '{indexPath}'.");

        var index = JsonSerializer.Deserialize<RegistryIndex>(File.ReadAllText(indexPath), JsonOpts.Default)
                    ?? throw new InvalidDataException($"Failed to parse '{indexPath}'.");
        return new Registry(path, index);
    }

    public BlockManifest GetBlock(string name)
    {
        if (_manifests.TryGetValue(name, out var cached)) return cached;
        var path = Path.Combine(Root, name, "block.json");
        if (!File.Exists(path))
            throw new FileNotFoundException($"Block '{name}' not found in registry (expected '{path}').");
        var manifest = JsonSerializer.Deserialize<BlockManifest>(File.ReadAllText(path), JsonOpts.Default)
                       ?? throw new InvalidDataException($"Failed to parse '{path}'.");
        _manifests[name] = manifest;
        return manifest;
    }

    public RegistryPreset? GetPreset(string name) =>
        Index.Presets.FirstOrDefault(p => p.Name == name);

    private static string Locate(string? explicitPath)
    {
        if (!string.IsNullOrEmpty(explicitPath))
        {
            var full = Path.GetFullPath(explicitPath);
            if (!Directory.Exists(full))
                throw new DirectoryNotFoundException($"Registry path '{full}' does not exist.");
            return full;
        }

        var cwd = Path.Combine(Directory.GetCurrentDirectory(), "registry");
        if (Directory.Exists(cwd)) return cwd;

        var asmDir = Path.GetDirectoryName(typeof(Registry).Assembly.Location) ?? "";
        var beside = Path.Combine(asmDir, "registry");
        if (Directory.Exists(beside)) return beside;

        throw new DirectoryNotFoundException(
            "Could not locate a registry. Pass --registry <path>, run from the MonoDreams repo root, or install the tool with a bundled registry.");
    }
}

internal static class JsonOpts
{
    public static readonly JsonSerializerOptions Default = new()
    {
        ReadCommentHandling = JsonCommentHandling.Skip,
        AllowTrailingCommas = true,
        PropertyNameCaseInsensitive = true,
    };

    public static readonly JsonSerializerOptions Pretty = new()
    {
        WriteIndented = true,
        DefaultIgnoreCondition = System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull,
    };
}

